function results = verifyDiffusionBiasDecomposition(varargin)
%VERIFYDIFFUSIONBIASDECOMPOSITION Audit density-dependent diffusion bias.
%
%   results = verifyDiffusionBiasDecomposition()
%   results = verifyDiffusionBiasDecomposition( ...
%       'nMolecules',[5 20 50 100])
%   results = verifyDiffusionBiasDecomposition('mode','mechanisms')
%
%   'density' sweeps molecule number and reports this truth ladder:
%     configured D
%     full-trajectory truth
%     focus-detectable truth
%     accepted-track truth
%     hard-gate-conditioned step MLE
%
%   'mechanisms' compares the baseline with hard-gate correction disabled,
%   wide gates, uniform excitation, and no CRB subtraction. The hard-gate
%   likelihood correction does not model JPDA competition, hypothesis
%   pruning, the association-confidence threshold, or focus selection.

    p = inputParser;
    p.FunctionName = 'verifyDiffusionBiasDecomposition';
    addParameter(p, 'mode', 'density');
    addParameter(p, 'nMolecules', [5 15 30 60 100]);
    addParameter(p, 'diffusionUm2PerS', 0.2);
    addParameter(p, 'dtS', 1e-3);
    addParameter(p, 'nFrames', 600);
    addParameter(p, 'boxSizeUm', [2 2]);
    addParameter(p, 'rngSeed', 11);
    addParameter(p, 'denseMolecules', 60);
    addParameter(p, 'extraOptions', {});
    parse(p, varargin{:});
    cfg = p.Results;
    cfg.mode = validatestring(cfg.mode, {'density', 'mechanisms'}, ...
        'verifyDiffusionBiasDecomposition', 'mode');
    if ~iscell(cfg.extraOptions)
        error('verifyDiffusionBiasDecomposition:BadOption', ...
            'extraOptions must be a cell array of name/value arguments.');
    end

    baseArgs = { ...
        'diffusionUm2PerS', cfg.diffusionUm2PerS, ...
        'dtS', cfg.dtS, ...
        'nFrames', cfg.nFrames, ...
        'boxSizeUm', cfg.boxSizeUm, ...
        'rngSeed', cfg.rngSeed, ...
        'makeFigure', false, ...
        'storePhotonEvents', false, ...
        'writeOutputs', false, ...
        'verbose', false};
    baseArgs = [baseArgs, cfg.extraOptions(:).'];

    switch cfg.mode
        case 'density'
            labels = cell(numel(cfg.nMolecules),1);
            argumentSets = cell(numel(cfg.nMolecules),1);
            for k = 1:numel(cfg.nMolecules)
                labels{k} = sprintf('N=%d (%.1f/um^2)', ...
                    cfg.nMolecules(k), ...
                    cfg.nMolecules(k)/prod(cfg.boxSizeUm));
                argumentSets{k} = [baseArgs, ...
                    {'nMolecules', cfg.nMolecules(k)}];
            end

        case 'mechanisms'
            dense = {'nMolecules', cfg.denseMolecules};
            labels = { ...
                'baseline'; ...
                'no hard-gate correction'; ...
                'wide gates'; ...
                'uniform excitation'; ...
                'no CRB subtraction'};
            argumentSets = { ...
                [baseArgs, dense]; ...
                [baseArgs, dense, {'gateCensoringCorrection', false}]; ...
                [baseArgs, dense, { ...
                    'associationGateChi2', 30, ...
                    'trackingPriorDiffusionUm2PerS', ...
                        cfg.diffusionUm2PerS, ...
                    'trackingMaxStepUm', 8*sqrt(4* ...
                        cfg.diffusionUm2PerS*cfg.dtS), ...
                    'minAssociationProbabilityForDiffusion', 0.5}]; ...
                [baseArgs, dense, { ...
                    'illuminationMode', 'uniform', ...
                    'maxLocalizationRadiusUm', ...
                        0.45*min(cfg.boxSizeUm)}]; ...
                [baseArgs, dense, {'crbCorrectionScale', 0}]};
    end

    rows = cell(numel(argumentSets),1);
    for k = 1:numel(argumentSets)
        fprintf('running %d/%d: %s ...\n', ...
            k, numel(argumentSets), labels{k});
        try
            out = simulateMembraneDiffusionParticleTracking( ...
                argumentSets{k}{:});
            rows{k} = summarizeRun(labels{k}, out);
        catch err
            fprintf(2, '  failed: %s\n', err.message);
            rows{k} = failedRow(labels{k});
        end
    end
    results = vertcat(rows{:});

    printLadder(results, cfg);
    printFlags(results);
end

% ----------------------------------------------------------------------------
function row = summarizeRun(label, out)
    diffusion = out.diffusion;
    truth = diffusion.truthValidation;
    density = out.densityDiagnostics;

    row = table();
    row.config = string(label);
    row.moleculesPerUm2 = ...
        out.options.actualMoleculeConcentrationPerUm2;
    row.moleculesInFocus = ...
        density.expectedMoleculesInEffectiveFocus;
    row.D_configured = truth.configuredDiffusionUm2PerS;
    row.D_truth_all = truth.fullTrajectoryLag1DiffusionUm2PerS;
    row.D_truth_detectable = ...
        truth.focusDetectableTruthLag1DiffusionUm2PerS;
    row.D_truth_accepted = ...
        truth.acceptedTrackTruthLag1DiffusionUm2PerS;
    row.D_step_mle = diffusion.DFisherMLEUm2PerS;
    row.D_msd = diffusion.DMsdCorrectedUm2PerS;

    row.keep_simulator = safeRatio( ...
        truth.fullTrajectoryLag1DiffusionUm2PerS, ...
        truth.configuredDiffusionUm2PerS);
    row.keep_detection = safeRatio( ...
        truth.focusDetectableTruthLag1DiffusionUm2PerS, ...
        truth.fullTrajectoryLag1DiffusionUm2PerS);
    row.keep_tracking = safeRatio( ...
        truth.acceptedTrackTruthLag1DiffusionUm2PerS, ...
        truth.focusDetectableTruthLag1DiffusionUm2PerS);
    row.keep_estimation = safeRatio( ...
        diffusion.DFisherMLEUm2PerS, ...
        truth.acceptedTrackTruthLag1DiffusionUm2PerS);
    row.keep_total = safeRatio( ...
        diffusion.DFisherMLEUm2PerS, ...
        truth.configuredDiffusionUm2PerS);

    row.crb_inflation = ...
        truth.localizationVarianceInflationOverFisher;
    row.identity_switch = truth.truthIdentitySwitchFraction;
    row.rejected_frac = diffusion.fractionRejectedForDiffusion;
    row.nonidentifiable_frac = ...
        diffusion.fractionNonidentifiablePositions;
    row.mean_K_fitted = ...
        meanFittedEmitterCount(out.localizationTable);
    row.nTracksUsed = diffusion.nTracksUsed;
    row.nStepsUsed = diffusion.nIndependentStepsForFisher;
    row.gate_acceptance = ...
        diffusion.meanHardGateAcceptanceProbability;
    row.refine_iters = ...
        diffusion.nTrackingRefinementIterations;
    row.prior_final = ...
        out.options.trackingPriorDiffusionUm2PerS;
end

% ----------------------------------------------------------------------------
function row = failedRow(label)
    row = table();
    row.config = string(label);
    names = {'moleculesPerUm2', 'moleculesInFocus', 'D_configured', ...
        'D_truth_all', 'D_truth_detectable', 'D_truth_accepted', ...
        'D_step_mle', 'D_msd', 'keep_simulator', 'keep_detection', ...
        'keep_tracking', 'keep_estimation', 'keep_total', ...
        'crb_inflation', 'identity_switch', 'rejected_frac', ...
        'nonidentifiable_frac', 'mean_K_fitted', 'nTracksUsed', ...
        'nStepsUsed', 'gate_acceptance', 'refine_iters', 'prior_final'};
    for k = 1:numel(names)
        row.(names{k}) = NaN;
    end
end

% ----------------------------------------------------------------------------
function printLadder(results, cfg)
    fprintf('\n=== diffusion bias ladder (%s sweep) ===\n', cfg.mode);
    fprintf('%-26s %8s %8s %8s %8s %8s %8s\n', ...
        'config', 'D_conf', 'truthAll', 'detect', 'accept', ...
        'D_step', 'D_msd');
    for k = 1:height(results)
        fprintf('%-26s %8.4f %8.4f %8.4f %8.4f %8.4f %8.4f\n', ...
            results.config(k), results.D_configured(k), ...
            results.D_truth_all(k), results.D_truth_detectable(k), ...
            results.D_truth_accepted(k), results.D_step_mle(k), ...
            results.D_msd(k));
    end

    fprintf('\n--- fraction of D surviving each stage ---\n');
    fprintf('%-26s %10s %10s %10s %10s %10s\n', ...
        'config', 'simulator', 'detection', 'tracking', ...
        'estimation', 'TOTAL');
    for k = 1:height(results)
        fprintf('%-26s %10.3f %10.3f %10.3f %10.3f %10.3f\n', ...
            results.config(k), results.keep_simulator(k), ...
            results.keep_detection(k), results.keep_tracking(k), ...
            results.keep_estimation(k), results.keep_total(k));
    end

    fprintf('\n--- diagnostics ---\n');
    fprintf('%-26s %7s %7s %8s %8s %8s %8s %8s\n', ...
        'config', 'inFocus', 'meanK', 'crbInfl', 'switch%', ...
        'reject%', 'nonId%', 'gateAcc');
    for k = 1:height(results)
        fprintf(['%-26s %7.2f %7.2f %8.3f %8.2f %8.1f ' ...
            '%8.1f %8.3f\n'], results.config(k), ...
            results.moleculesInFocus(k), results.mean_K_fitted(k), ...
            results.crb_inflation(k), ...
            100*results.identity_switch(k), ...
            100*results.rejected_frac(k), ...
            100*results.nonidentifiable_frac(k), ...
            results.gate_acceptance(k));
    end
    fprintf('\n');
end

% ----------------------------------------------------------------------------
function printFlags(results)
    fprintf('=== interpretation ===\n');
    anyFlag = false;

    if anyBelow(results.keep_simulator, 0.95)
        fprintf(['[simulator] Full-trajectory truth is low. Check Brownian ' ...
            'motion and boundary handling first.\n']);
        anyFlag = true;
    end
    if anyBelow(results.keep_detection, 0.90)
        fprintf(['[detection] Focus selection removes fast excursions. ' ...
            'Compare with the uniform-excitation run.\n']);
        anyFlag = true;
    end
    if anyBelow(results.keep_tracking, 0.90)
        fprintf(['[tracking] Association and confidence selection remove ' ...
            'long truth steps. Hard-gate conditioning fixes only the ' ...
            'geometric gate part.\n']);
        anyFlag = true;
    end
    if anyBelow(results.keep_estimation, 0.90)
        fprintf(['[estimation] D is lost after truth-step selection. Check ' ...
            'non-identifiable positions, emitter under-counting, and CRB ' ...
            'scaling.\n']);
        anyFlag = true;
    end

    finiteGate = results.gate_acceptance( ...
        isfinite(results.gate_acceptance));
    if ~isempty(finiteGate) && any(finiteGate < 0.98)
        fprintf(['[hard gate] Acceptance is below 0.98. Compare corrected, ' ...
            'uncorrected, and wide-gate runs; D should be stable after ' ...
            'correction.\n']);
        anyFlag = true;
    end

    finiteInflation = results.crb_inflation( ...
        isfinite(results.crb_inflation));
    if ~isempty(finiteInflation) && any(finiteInflation < 0.8)
        fprintf(['[CRB] Empirical localization MSE is below the Fisher ' ...
            'variance used for subtraction. Treat corrected MSD as a ' ...
            'sensitivity diagnostic.\n']);
        anyFlag = true;
    end

    lowEmitterCount = results.mean_K_fitted < ...
        0.8*results.moleculesInFocus;
    if any(lowEmitterCount & isfinite(results.mean_K_fitted))
        fprintf(['[model order] The selected emitter count remains low. ' ...
            'The BIC/Laplace score is still a singular-mixture ' ...
            'approximation and should be replaced before calling this BNP.\n']);
        anyFlag = true;
    end

    if ~anyFlag
        fprintf('No stage loses more than 10%% in this sweep.\n');
    end
    fprintf('\n');
end

% ----------------------------------------------------------------------------
function tf = anyBelow(values, threshold)
    values = values(isfinite(values));
    tf = ~isempty(values) && any(values < threshold);
end

% ----------------------------------------------------------------------------
function ratio = safeRatio(numerator, denominator)
    if ~isfinite(numerator) || ~isfinite(denominator) || denominator == 0
        ratio = NaN;
    else
        ratio = numerator/denominator;
    end
end

% ----------------------------------------------------------------------------
function count = meanFittedEmitterCount(localizationTable)
    if height(localizationTable) == 0
        count = NaN;
        return;
    end
    [~, uniqueRows] = unique(localizationTable.fitRegionId, 'stable');
    count = mean(localizationTable.jointEmitterCount(uniqueRows));
end
